sections.code:
WITH ranked AS (
  SELECT *, ROW_NUMBER() OVER (
    PARTITION BY test_id ORDER BY build_id DESC, run_id DESC
  ) AS rn
  FROM test_runs
)
SELECT test_id, status FROM ranked WHERE rn = 1 ORDER BY test_id;

